import { t as supabase } from "./client-DDYNpkNy.js";
// src/utils/remember.ts
var KEY = "bb_admin_session_marker";
/** Mark the current browser session as "remember me". */
function setRememberMe(remember) {
	if (remember) {
		localStorage.setItem(KEY, "1");
		sessionStorage.setItem(KEY, "1");
	} else {
		localStorage.removeItem(KEY);
		sessionStorage.setItem(KEY, "1");
	}
}
/**
* Call once on app boot. If the user did NOT choose "remember me" and this is
* a brand-new browser session (no sessionStorage marker), sign them out.
*/
async function enforceRememberMe() {
	try {
		const { data } = await supabase.auth.getSession();
		if (!data.session) return;
		const remembered = localStorage.getItem(KEY) === "1";
		const sameTab = sessionStorage.getItem(KEY) === "1";
		if (!remembered && !sameTab) await supabase.auth.signOut();
		else if (!sameTab) sessionStorage.setItem(KEY, "1");
	} catch {}
}
function clearRememberMarker() {
	localStorage.removeItem(KEY);
	sessionStorage.removeItem(KEY);
}
export { clearRememberMarker, enforceRememberMe, setRememberMe };
